// One line per `name`, from a long frame (time, name, value), on a time axis
// of its own: each tab of this dashboard covers different years, so its charts
// do not follow the dashboard's time range. The colours are the map's: kepler
// hands its palette out over the names in sorted order, and so does this.
//
// It also drives the dashboard through variables, each one switched off by
// an empty name in the constants:
// - PICK: a click on a line follows that animal; a click on the line of the
//   animal followed lets it go.
// - LO, HI: dragging across the chart picks a window of days, written as
//   month-day so that it holds for any year; the toolbox clears it. The chart
//   does not filter itself: it keeps the whole year the window is cut from.
// - OFF: a click in the legend hides a line and writes the names hidden,
//   comma separated, for the other panels to leave out.
// - NOW: the map's playhead, drawn as a bar. It is read from the URL and only
//   the bar moves, so playback never runs a query.
// - TAG: hovering publishes the moment under the pointer on Grafana's shared
//   cursor, and the map marks where each animal was then.
// @constants begin
const UNIT = 'km';
const PALETTE = ['#4cc9f0',  '#f72585',  '#ffb703',  '#80ed99',  '#b388eb',  '#ff7f51',  '#2ec4b6',  '#e9ff70',  '#ff99c8',  '#90e0ef',  '#f4a261',  '#a3b18a'];
const PICK = 'bird';
const LO = 'g_lo';
const HI = 'g_hi';
const OFF = '';
const NOW = 'g_now';
const TAG = 'animal-movement-gulls';
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const read = (name) => (name ? context.grafana.replaceVariables('${' + name + '}') : '');

const frame = context.panel.data.series[0];
const column = (name) => Array.from(frame?.fields.find((f) => f.name === name)?.values ?? []);
const times = column('time').map(Number);
const names = column('name');
const values = column('value');

const lines = new Map();
names.forEach((name, i) => {
  if (!lines.has(name)) {
    lines.set(name, []);
  }
  lines.get(name).push([times[i], values[i]]);
});
const sorted = [...lines.keys()].sort();
// Past eight lines a legend and a shared tooltip are noise: hover a line instead.
const few = sorted.length <= 8;

chart.off('click');
if (PICK) {
  chart.on('click', (event) => {
    if (event.componentType !== 'series' || event.seriesId === 'now') {
      return;
    }
    const next = read(PICK) === event.seriesName ? '' : event.seriesName;
    location.partial({ ['var-' + PICK]: next }, true);
  });
}

// The legend comes back from the variable on every redraw.
const hidden = OFF ? read(OFF).split(',').filter(Boolean) : [];
chart.off('legendselectchanged');
if (OFF) {
  chart.on('legendselectchanged', (event) => {
    const off = sorted.filter((name) => event.selected[name] === false);
    location.partial({ ['var-' + OFF]: off.join(',') }, true);
  });
}

// The window: whole days, never empty, never across New Year.
const DAY = 86400000;
let first = Infinity;
for (const t of times) {
  first = Math.min(first, t);
}
const year = Number.isFinite(first) ? new Date(first).getUTCFullYear() : 2000;
const monthDay = (ms) => new Date(ms).toISOString().slice(5, 10);
const dayOf = (md) => Date.parse(`${year}-${md}T00:00:00Z`);
const drawBrush = (range) =>
  chart.dispatchAction({
    type: 'brush',
    areas: range ? [{ brushType: 'lineX', xAxisIndex: 0, coordRange: range }] : [],
  });
const publish = (range) =>
  location.partial(
    { ['var-' + LO]: range ? monthDay(range[0]) : '', ['var-' + HI]: range ? monthDay(range[1] - DAY) : '' },
    true
  );
chart.off('brushEnd');
chart.off('brush');
if (LO) {
  chart.on('brushEnd', (event) => {
    const area = event.areas[0];
    if (!area || !area.coordRange) {
      publish(undefined);
      return;
    }
    const lo = Math.max(Math.floor(area.coordRange[0] / DAY) * DAY, Date.UTC(year, 0, 1));
    const hi = Math.min(Math.max(Math.ceil(area.coordRange[1] / DAY) * DAY, lo + DAY), Date.UTC(year + 1, 0, 1));
    publish([lo, hi]);
    setTimeout(() => drawBrush([lo, hi]), 0);
  });
  chart.on('brush', (event) => {
    if (event.command === 'clear') {
      publish(undefined);
    }
  });
  // Every redraw wipes the brush: draw it back from the variables, which is
  // also how a shared link arrives with its window.
  const current = [dayOf(read(LO)), dayOf(read(HI)) + DAY];
  setTimeout(() => {
    if (current.every(Number.isFinite)) {
      drawBrush(current);
    }
  }, 0);
}

// The bar at the instant the map is playing.
const nowMs = () => {
  const raw = NOW ? new URLSearchParams(location.getLocation().search).get('var-' + NOW) : null;
  const ms = raw ? Date.parse(raw) : NaN;
  return Number.isFinite(ms) ? ms : null;
};
const nowLine = (at) =>
  at === null
    ? { data: [] }
    : {
        symbol: 'none',
        silent: true,
        animation: false,
        label: { show: false },
        lineStyle: { color: theme.colors.text.primary, width: 1.5, type: 'solid' },
        data: [{ xAxis: at }],
      };
let drawnAt = nowMs();
const stopNow = NOW
  ? location.getHistory().listen(() => {
      const at = nowMs();
      if (at !== drawnAt && !chart.isDisposed()) {
        drawnAt = at;
        chart.setOption({ series: [{ id: 'now', markLine: nowLine(at) }] }, { lazyUpdate: true });
      }
    })
  : () => {};

// The shared cursor, by hand: Business Charts takes no part in it. Whole
// hours, so the map is asked again only when the hour changes; tagged, so the
// chart never answers its own.
const bus = context.grafana.eventBus;
const zr = chart.getZr();
let published = null;
const hoverAt = (ms) => {
  if (ms === published) {
    return;
  }
  published = ms;
  bus.publish(
    ms === null
      ? { type: 'data-hover-clear', payload: {}, tags: new Set([TAG]) }
      : { type: 'data-hover', payload: { point: { time: ms } }, tags: new Set([TAG]) }
  );
};
const onMove = (event) => {
  const at = [event.offsetX, event.offsetY];
  // Dragging draws the brush: the pointer is not asking about a moment.
  if (event.event?.buttons || !chart.containPixel({ gridIndex: 0 }, at)) {
    hoverAt(null);
    return;
  }
  const ms = Math.round(chart.convertFromPixel({ gridIndex: 0 }, at)[0] / 3600000) * 3600000;
  hoverAt(Number.isFinite(ms) ? ms : null);
};
const onLeave = () => hoverAt(null);
if (TAG) {
  zr.on('mousemove', onMove);
  zr.on('globalout', onLeave);
}
const stopHover = () => {
  if (TAG) {
    zr.off('mousemove', onMove);
    zr.off('globalout', onLeave);
    hoverAt(null);
  }
};

const option = {
  animation: false,
  backgroundColor: 'transparent',
  color: PALETTE,
  tooltip: {
    trigger: few ? 'axis' : 'item',
    valueFormatter: (v) => (v == null ? '–' : `${Number(v).toLocaleString()} ${UNIT}`),
  },
  legend: {
    show: few,
    type: 'scroll',
    bottom: 0,
    textStyle: { color: muted },
    data: sorted,
    selected: Object.fromEntries(sorted.map((name) => [name, !hidden.includes(name)])),
  },
  grid: { left: 8, right: 16, top: 30, bottom: few ? 32 : 8, containLabel: true },
  xAxis: { type: 'time', axisLabel: { color: muted, hideOverlap: true } },
  yAxis: {
    type: 'value',
    name: UNIT,
    nameTextStyle: { color: muted },
    axisLabel: { color: muted },
    splitLine: { lineStyle: { color: theme.colors.border.weak } },
  },
  series: [
    ...sorted.map((name) => ({
      name,
      type: 'line',
      data: lines.get(name),
      showSymbol: false,
      triggerLineEvent: Boolean(PICK),
      lineStyle: { width: 1.2 },
      emphasis: { focus: 'series' },
    })),
    // No data of its own: only the bar.
    { id: 'now', type: 'line', data: [], silent: true, tooltip: { show: false }, markLine: nowLine(drawnAt) },
  ],
};
if (LO) {
  option.toolbox = {
    right: 8,
    top: 0,
    itemSize: 14,
    feature: { brush: { type: ['lineX', 'clear'], title: { lineX: 'Pick a window of days', clear: 'Clear the window' } } },
  };
  option.brush = {
    xAxisIndex: 0,
    brushType: 'lineX',
    brushMode: 'single',
    transformable: true,
    removeOnClick: false,
    brushStyle: { color: 'rgba(128, 128, 128, 0.14)', borderColor: muted, borderWidth: 1 },
  };
}

return {
  version: 2,
  option,
  unsubscribe: () => {
    stopNow();
    stopHover();
  },
};

// Kilometres by two-hour block of the day and by month, from a frame (month,
// hour, value), the hour the block's start in UTC. A click on a cell keeps
// that block of that month on the other panels; a click on an hour's label
// keeps the block in every month, a click on a month's label the whole month;
// the same click again lets it go. The cell or the row picked is outlined.
// @constants begin
const UNIT = 'km';
const HOUR = 'g_hour';
const MONTH = 'g_month';
const COLOR = '#4cc9f0';
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const read = (name) => context.grafana.replaceVariables('${' + name + '}');
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const HOURS = Array.from({ length: 12 }, (_, i) => String(i * 2).padStart(2, '0'));

const frame = context.panel.data.series[0];
const column = (name) => Array.from(frame?.fields.find((f) => f.name === name)?.values ?? []);
const months = column('month').map(Number);
const hours = column('hour').map(Number);
const values = column('value').map(Number);

const pickedHour = parseInt(read(HOUR), 10);
const pickedMonth = parseInt(read(MONTH), 10);
const isPicked = (h, m) =>
  (Number.isFinite(pickedHour) || Number.isFinite(pickedMonth)) &&
  (!Number.isFinite(pickedHour) || pickedHour === h) &&
  (!Number.isFinite(pickedMonth) || pickedMonth === m);

let top = 0;
const data = months.map((m, i) => {
  top = Math.max(top, values[i]);
  const picked = isPicked(hours[i], m);
  return {
    value: [hours[i] / 2, m - 1, values[i]],
    itemStyle: picked ? { borderColor: theme.colors.text.primary, borderWidth: 2 } : undefined,
  };
});

const set = (hour, month) => {
  const same = hour === (Number.isFinite(pickedHour) ? pickedHour : null) && month === (Number.isFinite(pickedMonth) ? pickedMonth : null);
  location.partial(
    {
      ['var-' + HOUR]: same || hour === null ? '' : String(hour),
      ['var-' + MONTH]: same || month === null ? '' : String(month),
    },
    true
  );
};
chart.off('click');
chart.on('click', (event) => {
  if (event.componentType === 'series') {
    set(event.value[0] * 2, event.value[1] + 1);
  } else if (event.componentType === 'xAxis') {
    set(Number(event.value), null);
  } else if (event.componentType === 'yAxis') {
    set(null, MONTHS.indexOf(event.value) + 1);
  }
});

return {
  backgroundColor: 'transparent',
  tooltip: {
    formatter: (p) =>
      `${MONTHS[p.value[1]]}, ${HOURS[p.value[0]]}:00–${String(p.value[0] * 2 + 2).padStart(2, '0')}:00 UTC<br/><b>${Number(p.value[2]).toLocaleString()} ${UNIT}</b>`,
  },
  grid: { left: 8, right: 16, top: 8, bottom: 36, containLabel: true },
  xAxis: {
    type: 'category',
    data: HOURS,
    triggerEvent: true,
    name: 'UTC',
    nameLocation: 'end',
    nameTextStyle: { color: muted },
    axisLabel: { color: muted },
    splitArea: { show: false },
  },
  yAxis: { type: 'category', data: MONTHS, inverse: true, triggerEvent: true, axisLabel: { color: muted } },
  visualMap: {
    min: 0,
    max: Math.max(top, 1),
    calculable: false,
    orient: 'horizontal',
    left: 'center',
    bottom: 0,
    itemHeight: 120,
    itemWidth: 10,
    textStyle: { color: muted },
    text: [`${Math.round(top).toLocaleString()} ${UNIT}`, '0'],
    inRange: { color: [theme.colors.background.secondary, COLOR] },
  },
  series: [{ type: 'heatmap', data, emphasis: { itemStyle: { borderColor: theme.colors.text.primary, borderWidth: 1 } } }],
};

