// A histogram from a frame (bin, n), `bin` each bar's lower edge, the last bar
// open-ended. Dragging across it writes the range picked to two variables
// (LO and HI, HI empty when the range runs off the end); the other panels
// keep only what falls inside it, and this one keeps showing everything, so
// the range can be moved. The toolbox clears it.
// @constants begin
const UNIT = 'km a day';
const COUNTED = 'jaguar-days';
const LO = 'j_lo';
const HI = 'j_hi';
const STEP = 1;
const COLOR = '#f72585';
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const read = (name) => context.grafana.replaceVariables('${' + name + '}');

const frame = context.panel.data.series[0];
const column = (name) => Array.from(frame?.fields.find((f) => f.name === name)?.values ?? []);
const bins = column('bin').map(Number);
const counts = column('n').map(Number);
const last = bins.length - 1;
const label = (i) => (i === last ? `${bins[i]}+` : `${bins[i]}–${bins[i] + STEP}`);

// Bars are slots on a category axis; ranges come and go as slots.
const slotOf = (value) => Math.max(0, Math.min(last, Math.round(value / STEP)));
const drawBrush = (slots) =>
  chart.dispatchAction({
    type: 'brush',
    areas: slots ? [{ brushType: 'lineX', xAxisIndex: 0, coordRange: slots }] : [],
  });
const publish = (slots) =>
  location.partial(
    {
      ['var-' + LO]: slots ? String(bins[slots[0]]) : '',
      ['var-' + HI]: slots && slots[1] < last ? String(bins[slots[1]] + STEP) : '',
    },
    true
  );

chart.off('brushEnd');
chart.off('brush');
chart.on('brushEnd', (event) => {
  const area = event.areas[0];
  if (!area || !area.coordRange) {
    publish(undefined);
    return;
  }
  const slots = [Math.max(0, Math.round(area.coordRange[0])), Math.min(last, Math.round(area.coordRange[1]))];
  publish(slots);
  setTimeout(() => drawBrush(slots), 0);
});
chart.on('brush', (event) => {
  if (event.command === 'clear') {
    publish(undefined);
  }
});

const lo = parseFloat(read(LO));
const hi = parseFloat(read(HI));
setTimeout(() => {
  chart.dispatchAction({ type: 'takeGlobalCursor', key: 'brush', brushOption: { brushType: 'lineX', brushMode: 'single' } });
  if (Number.isFinite(lo)) {
    drawBrush([slotOf(lo), Number.isFinite(hi) ? slotOf(hi - STEP) : last]);
  }
}, 0);

return {
  animation: false,
  backgroundColor: 'transparent',
  tooltip: { trigger: 'axis', formatter: (items) => `${label(items[0].dataIndex)} ${UNIT}<br/><b>${items[0].value.toLocaleString()}</b> ${COUNTED}` },
  toolbox: {
    right: 8,
    top: 0,
    itemSize: 14,
    feature: { brush: { type: ['lineX', 'clear'], title: { lineX: 'Pick a range', clear: 'Clear the range' } } },
  },
  brush: {
    xAxisIndex: 0,
    brushType: 'lineX',
    brushMode: 'single',
    transformable: true,
    brushStyle: { color: 'rgba(128, 128, 128, 0.14)', borderColor: muted, borderWidth: 1 },
    outOfBrush: { colorAlpha: 0.3 },
  },
  grid: { left: 8, right: 16, top: 30, bottom: 8, containLabel: true },
  xAxis: {
    type: 'category',
    data: bins.map((b, i) => (i === last ? `${b}+` : String(b))),
    name: UNIT,
    nameLocation: 'end',
    nameTextStyle: { color: muted },
    axisLabel: { color: muted, interval: 4 },
    axisTick: { show: false },
  },
  yAxis: {
    type: 'value',
    name: COUNTED,
    nameTextStyle: { color: muted },
    axisLabel: { color: muted },
    splitLine: { lineStyle: { color: theme.colors.border.weak } },
  },
  series: [{ type: 'bar', data: counts, barCategoryGap: '8%', itemStyle: { color: COLOR } }],
};

// One line per `name` across the twelve months, from a long frame (month,
// name, value). The colours are the map's: kepler hands its palette out over
// the names in sorted order, and so does this.
//
// It drives the dashboard through variables:
// - MONTH: a click anywhere in a month's column keeps that month on the other
//   panels, every year of it; a click on the same month lets it go.
// - OFF: a click in the legend hides a line and writes the names hidden,
//   comma separated, for the other panels to leave out.
// - NOW: the month the map is playing, as a bar, read from the URL; only the
//   bar moves, so playback never runs a query.
// @constants begin
const UNIT = '°N';
const PALETTE = ['#4cc9f0',  '#f72585',  '#ffb703',  '#80ed99',  '#b388eb',  '#ff7f51',  '#2ec4b6',  '#e9ff70',  '#ff99c8',  '#90e0ef',  '#f4a261',  '#a3b18a'];
const MONTH = 'o_month';
const OFF = 'o_off';
const NOW = 'o_now';
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const read = (name) => context.grafana.replaceVariables('${' + name + '}');
const LABELS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

const frame = context.panel.data.series[0];
const column = (name) => Array.from(frame?.fields.find((f) => f.name === name)?.values ?? []);
const months = column('month');
const names = column('name');
const values = column('value');

const lines = new Map();
names.forEach((name, i) => {
  if (!lines.has(name)) {
    lines.set(name, new Array(12).fill(null));
  }
  lines.get(name)[Number(months[i]) - 1] = values[i];
});
const sorted = [...lines.keys()].sort();

const hidden = read(OFF).split(',').filter(Boolean);
chart.off('legendselectchanged');
chart.on('legendselectchanged', (event) => {
  const off = sorted.filter((name) => event.selected[name] === false);
  location.partial({ ['var-' + OFF]: off.join(',') }, true);
});

// A month, by its whole column rather than by its points, which are small.
const picked = parseInt(read(MONTH), 10);
const zr = chart.getZr();
const onClick = (event) => {
  const at = [event.offsetX, event.offsetY];
  if (!chart.containPixel({ gridIndex: 0 }, at)) {
    return;
  }
  const index = Math.round(chart.convertFromPixel({ gridIndex: 0 }, at)[0]);
  if (index >= 0 && index < 12) {
    location.partial({ ['var-' + MONTH]: picked === index + 1 ? '' : String(index + 1) }, true);
  }
};
zr.on('click', onClick);

const nowMonth = () => {
  const raw = new URLSearchParams(location.getLocation().search).get('var-' + NOW);
  const ms = raw ? Date.parse(raw) : NaN;
  return Number.isFinite(ms) ? new Date(ms).getUTCMonth() : null;
};
const bars = (now) => ({
  symbol: 'none',
  silent: true,
  animation: false,
  data: [
    ...(Number.isFinite(picked)
      ? [{ xAxis: picked - 1, lineStyle: { color: theme.colors.primary.text, width: 2, type: 'dashed' }, label: { show: true, formatter: 'picked', color: muted } }]
      : []),
    ...(now === null ? [] : [{ xAxis: now, lineStyle: { color: theme.colors.text.primary, width: 1.5, type: 'solid' }, label: { show: false } }]),
  ],
});
let drawnAt = nowMonth();
const stopNow = location.getHistory().listen(() => {
  const at = nowMonth();
  if (at !== drawnAt && !chart.isDisposed()) {
    drawnAt = at;
    chart.setOption({ series: [{ id: 'marks', markLine: bars(at) }] }, { lazyUpdate: true });
  }
});

const option = {
  animation: false,
  backgroundColor: 'transparent',
  color: PALETTE,
  tooltip: {
    trigger: 'axis',
    valueFormatter: (v) => (v == null ? '–' : `${Number(v).toLocaleString()}${UNIT}`),
  },
  legend: {
    type: 'scroll',
    bottom: 0,
    textStyle: { color: muted },
    data: sorted,
    selected: Object.fromEntries(sorted.map((name) => [name, !hidden.includes(name)])),
  },
  grid: { left: 8, right: 16, top: 30, bottom: 32, containLabel: true },
  xAxis: { type: 'category', data: LABELS, boundaryGap: false, axisLabel: { color: muted } },
  yAxis: {
    type: 'value',
    name: UNIT,
    scale: true,
    nameTextStyle: { color: muted },
    axisLabel: { color: muted },
    splitLine: { lineStyle: { color: theme.colors.border.weak } },
  },
  series: [
    ...sorted.map((name) => ({
      name,
      type: 'line',
      data: lines.get(name),
      connectNulls: true,
      symbolSize: 4,
      emphasis: { focus: 'series' },
    })),
    { id: 'marks', type: 'line', data: [], silent: true, tooltip: { show: false }, markLine: bars(drawnAt) },
  ],
};

return {
  version: 2,
  option,
  unsubscribe: () => {
    stopNow();
    zr.off('click', onClick);
  },
};
